sys_script_include.script:
var CheckEventLocation = Class.create();
CheckEventLocation.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	isLocationAvailable:function(){
		var location = this.getParameter('sysparm_location');
        var date = this.getParameter('sysparm_event_date');
        var gr = new GlideRecord('x_1790233_event_ma_event_record');
        gr.addQuery('location', location);
        gr.addQuery('event_date', date);
        gr.query();
        return gr.hasNext() ? 'false' : 'true';
	},
    type: 'CheckEventLocation'
});
